UPDATE companies SET description='Agapé Plastics, Inc. is headquartered in Walker, Michigan. The company was founded in 1973 and remains family-owned and WBENC-certified as a woman-owned business. What began as a regional injection molding operation has grown into a vertically integrated, automotive-grade manufacturing partner serving Tier 1 suppliers and industrial OEMs across North America.

The company provides custom injection molding, insert injection molding, in-house tool room and mold design, reverse engineering, metal-to-plastic conversion, post-mold assembly, plastic welding (including sonic and infrared welding), manufacturing and assembly, plastic part design optimization, and injection mold tooling services. Operations run on 48 injection molding machines ranging from 85 to 1,560 tons of clamping force within a 144,000-square-foot facility that operates 24 hours a day across three shifts with approximately 230 employees.

Agapé Plastics primarily serves the automotive industry, supplying Tier 1 suppliers and OEMs with safety systems, steering column components, NVH components, and complex interior and exterior assemblies. Beyond automotive, the company works with heavy-duty truck and commercial vehicle manufacturers, agricultural equipment producers, hand and power tool brands, renewable energy and industrial equipment companies, as well as the appliance, furniture, RV and marine, and powersports sectors.

The company emphasizes engineering-led, vertically integrated program management from quote through tool build and production launch, with leadership directly involved in operations. Its quality systems are built to IATF 16949:2016 and ISO 14001 standards, featuring in-house CMM inspection and process validation. WBENC certification supports supplier diversity initiatives for customers.', certifications=ARRAY['IATF 16949:2016','ISO 14001','WBENC (Woman-Owned Business Certification)']::text[], profile='{"capabilities": ["Custom Injection Molding", "Insert Injection Molding", "In-House Tool Room and Mold Design", "Reverse Engineering", "Metal-to-Plastic Conversion", "Post-Mold Assembly", "Plastic Welding", "Sonic Welding", "Infrared Welding", "Manufacturing & Assembly", "Plastic Part Design Optimization", "Injection Mold Tooling Services", "Value Engineering (VA/VE)", "Prototyping", "Production", "Assembly", "Testing"], "industries": ["Automotive", "Agricultural", "Appliance", "Furniture", "Hand Tools", "Large Trucks", "Renewable Energy", "RV & Marine", "Powersports", "Heavy-Duty Truck", "Commercial Vehicle", "Industrial Equipment", "Medical", "Office Furniture"], "materials": ["Thermoplastics", "High-performance resins"], "equipment": ["48 injection molding machines (85\u20131,560 ton)", "Horizontal and vertical injection molding presses", "CMM inspection equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Vertically integrated engineering, tooling, molding, and assembly under one accountable partner", "48 injection molding machines (85\u20131,560 ton) with 24-hour production capability", "IATF 16949:2016 and ISO 14001 certified quality systems with in-house CMM inspection", "WBENC-certified woman-owned business", "Family-owned with leadership directly involved in daily operations"], "facts_used": ["Founded in 1973 -> db", "Family-owned and WBENC-certified -> /", "Vertically integrated automotive-grade manufacturing partner -> /", "48 injection molding machines (85\u20131,560 ton) -> /", "144,000 sq ft facility -> /", "24-hour production -> /", "230 employees -> /", "Three shifts -> /", "Industries: automotive, agricultural, appliance, furniture, hand tools, large trucks, renewable energy, RV & marine, powersports -> /", "Heavy-duty truck, commercial vehicle, agricultural equipment, hand and power tool brands, renewable energy, industrial equipment -> /", "Certifications: IATF 16949:2016, ISO 14001, WBENC -> /", "Processes: custom injection molding, insert injection molding, in-house tool room, mold design, reverse engineering, metal-to-plastic conversion, post-mold assembly, plastic welding, sonic welding, infrared welding, manufacturing & assembly, plastic part design optimization, injection mold tooling services, value engineering -> /", "Engineering-led vertically integrated program management -> /", "Leadership directly involved in operations -> /", "Headquarters Walker, Michigan -> db", "Employee count 230 -> db", "Certifications ISO14001, IATF16949 -> db"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='agap-plastics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Akron Steel Fabricators (ASF) was established in 1946 in Akron, Ohio, as an innovator in the tire and rubber industries. Now operating as a division of the Poling Group, the company runs a 42,000-square-foot facility on Manchester Road that houses design, engineering, fabrication, and assembly under one roof.

The division provides custom CAD design and engineering through to finished machinery, specializing in rubber handling equipment. Its product lines include calenders and ancillary equipment, mill blenders, slab cutter/feeders, batch-off machines for mixing operations, and the next-generation S2S Series Slitter for cold slab stock cutting. ASF also builds OEM machinery solutions and offers machine remanufacturing, calibration, installation, and on-site support.

ASF serves the tire, rubber, plastic, and steel industries worldwide, with a strong presence in automotive testing. Customers range from original equipment manufacturers needing proven machinery to plants requiring custom fabrication and spare parts for existing lines.

The company emphasizes that its deep industry knowledge and in-house engineering staff allow it to build a high level of reliability into every machine, delivering fast response to custom fabrication needs and proven OEM solutions.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Custom CAD design and engineering", "Fabrication and assembly", "Calender manufacturing", "Mill blender manufacturing", "Slab cutter/feeder manufacturing", "Batch-off equipment manufacturing", "S2S Series Slitter manufacturing", "Machine remanufacturing", "Calibration services", "Installation and start-up", "Remote and on-site support", "Custom engineering", "Custom software development", "Spare parts supply", "Controller upgrades", "Tire testing equipment manufacturing", "Rubber processing equipment manufacturing", "Factory management software", "Tire visual inspection systems", "Tire waveform analysis", "PLC/Unix API library", "Tread label management"], "industries": ["Automotive Testing", "Tire", "Rubber", "Plastic", "Steel"], "materials": ["Steel", "Rubber", "Plastic"], "equipment": ["TWA-18 Tire/Wheel Assembly", "Upper Spindle Assembly", "S2S Series Slitter", "MCX75 Motorcycle TU", "CX111 PC/LT TU", "X150 Truck/Bus TU", "DB111 Balance Testing", "UFT111 Universal Flash Trimmer", "AG2540 Agriculture Runout", "TRM92 Tire Geometry", "PGM Profile Generating Machine", "Sidewall Grinder", "Calenders", "Calender Line Equipment", "Cooling Drums", "Post Cure Inflator", "Precision Test Rims", "Quick Rim Changeover", "TTOC6 Controller", "TAIR-Tire Automatic Inflation Regulator", "Laser Verification Wheel", "RRO Probe Replacement", "Auto-Adjust Width Chuck", "Timing Belt Center Conveyor", "Spindle Motor/Gearbox", "Retractable Stripping Wheel", "Retro-Fit Stripping Wheel", "Anti-mischucking System", "Sorting Elevator", "Multi-level Sorting Conveyor", "Auto-position Shoulder", "Auto-position Center", "Grind Dust Removal System", "Exit Station Marker", "Internal Marker Tran