UPDATE companies SET description='Alaska Packaging Inc. was established in 2002 in Anchorage, Alaska. The company operates as a provider of packaging solutions specifically engineered for perishable commodities.

Its product line consists of packaging materials that carry FDA approval for safety and compliance, designed to maintain the freshness and structural integrity of shipments throughout the supply chain. The firm also offers tailored fulfillment services, adapting packaging and logistics to individual customer requirements.

The primary markets served are commercial fishing and agriculture, sectors where temperature-sensitive and time-critical shipments demand reliable containment. Examples include packaging for fresh seafood and perishable produce.

Alaska Packaging differentiates itself through a focus on innovation in perishable-item packaging, combining regulatory compliance with customized fulfillment to reduce spoilage risk and meet stringent industry standards.', certifications=ARRAY['FDA Approved']::text[], profile='{"capabilities": ["Tailored Fulfillment Services", "Perishable Goods Packaging", "FDA-Compliant Packaging"], "industries": ["Fishing", "Agriculture"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["FDA-approved packaging materials for safety and compliance", "Tailored fulfillment services customized to customer needs", "Specialization in perishable-item packaging for fishing and agriculture", "Innovative solutions to maintain shipment freshness and integrity"], "facts_used": ["Founded in 2002 -> db", "Headquartered in Anchorage, Alaska -> db", "Specializes in packaging for perishable items -> db", "Packaging materials FDA approved -> db", "Serves fishing and agriculture industries -> db", "Offers tailored fulfillment services -> db"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='alaska-packaging' AND approved AND profile IS NULL;
UPDATE companies SET description='Alcam Metal Distributors, based in Golden, Colorado, has served the Denver metropolitan area since 1994. The minority‑owned company began as a metal distribution center and incorporated in 1999, later moving to its current facility off I‑70 and Ward Road in 2009.

The company operates as a one‑stop shop for metals including carbon steel, stainless steel, aluminum, copper, brass, Fibergrate fiberglass gratings, and Indital ornamental components. Its services span distribution, custom fabrication (cut‑to‑length, MIG/TIG welding, braking, bending, milling, CNC plasma cutting, and shearing), CAD design with finite‑element analysis, shop drawings, and installation. A 2015 expansion added a dedicated steel supply and fabrication center, and a fleet of trucks provides delivery across the Denver metro region.

Alcam’s project portfolio centers on public‑works and commercial construction. It supplied and installed structural and miscellaneous metals for RTD Fastracks lines A, B, G, N, R, and W, as well as Denver Union Station. Current work includes projects at Denver International Airport and the Denver Center for the Performing Arts, alongside other public and private contracts in the region.

The company emphasizes rapid response, offering same‑day turnaround on rush orders, and stresses long‑term customer relationships — many clients have remained since the 1994 founding. Its differentiation rests on broad material availability, in‑house design and fabrication capabilities, and a minority‑owned certification that supports supplier‑diversity goals.', certifications=ARRAY['MINORITY-OWNED']::text[], profile='{"capabilities": ["Metal distribution", "Custom fabrication", "Cut-to-length", "MIG welding", "TIG welding", "Braking (press brake)", "Bending", "Milling", "CNC plasma cutting", "Shearing", "CAD design", "Finite element analysis", "Shop drawings", "Installation", "Subcontracting", "Delivery"], "industries": ["Construction", "Public transportation", "Aviation", "Arts and entertainment", "Government"], "materials": ["Carbon steel", "Stainless steel", "Aluminum", "Copper", "Brass", "Fiberglass reinforced plastic (Fibergrate)", "Indital ornamental metal components", "Plastics"], "equipment": ["CNC plasma cutting system", "MIG welding equipment", "TIG welding equipment", "Press brake", "Shear", "Milling machine", "Delivery trucks"], "volume": "", "lead_time": "Same-day turnaround available for rush orders", "tolerances": "", "built_on": ["Same-day turnaround on rush orders", "One-stop shop for carbon, stainless, aluminum, copper, brass, Fibergrate, and Indital ornamental metals", "In-house CAD design, FEA, and fabrication drawings", "Fleet delivery throughout Denver metro area", "Minority-owned business certification"], "facts_used": ["Founded 1994 -> / (ALCAM HISTORY)", "Headquarters Golden, CO -> / (contact info)", "Minority-owned certification -> db", "Services: distribution, fabrication, subcontracting -> /services", "Materials: carbon, stainless, aluminum, copper, brass, Fibergrate, Indital -> /services and /", "Equipment: CNC plasma cutting, MIG/TIG welding, braking, bending, milling, shearing -> /services", "Projects: RTD Fastracks lines, Denver Unio