UPDATE companies SET description='Badger Wire, Inc. was founded in 1989 in Waukesha, Wisconsin, to extrude large gauge wire. The company has built a reputation for extrusion capabilities, quality, and service since its inception.

The company manufactures a range of extruded products including primary wire, battery cable, booster cable, trailer cable, auto duplex, PVC tubes, tubing, and multi-conductor wire. Using Davis-Standard extrusion equipment, Badger Wire maintains close tolerances and consistent quality while achieving high extrusion speeds. The facility can produce substantial footage of heavy gauge wire within one to three weeks and offers smaller minimum quantity runs than many larger competitors.

Badger Wire serves industries such as Power, Truck Trailers, Lawn & Garden, and Marine. Its products are used in applications requiring insulated wire, cable, and tubing, including UL and CSA rated wire.

The company emphasizes responsiveness due to its size relative to larger manufacturers, offering smaller minimum runs and keeping finished product in stock for immediate shipment or raw material on hand for quick production. This service focus, combined with technical capabilities, aims to provide high-quality battery cable at competitive prices with service that customers find difficult to match among U.S. insulated wire manufacturers.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Wire extrusion", "Cable manufacturing", "Tubing extrusion", "Multi-conductor wire production", "UL/CSA rated wire production", "Custom extrusion"], "industries": ["Power", "Truck Trailers", "Lawn & Garden", "Marine"], "materials": ["PVC"], "equipment": ["Davis-Standard extrusion equipment"], "volume": "", "lead_time": "1-3 weeks for heavy gauge; immediate for stocked items", "tolerances": "Close tolerances", "built_on": ["Smaller minimum quantity runs than larger manufacturers", "Heavy gauge wire production within 1-3 weeks", "Finished product stocked for immediate shipment", "Raw material available for quick turnaround", "Davis-Standard extrusion equipment for speed and close tolerances"], "facts_used": ["Founded in 1989 in Waukesha, Wisconsin -> /about", "ISO 9001:2015 certified since 1999 -> /about", "Manufactures primary wire, battery cable, booster cable, trailer cable, auto duplex, PVC tubes, tubing, multi-conductor wire -> /", "Uses Davis-Standard extrusion equipment -> /about", "Offers smaller minimum quantity runs than larger manufacturers -> /about", "Heavy gauge wire production within 1-3 weeks -> /about", "Stocks finished product for immediate shipment -> /about", "Serves Power, Truck Trailers, Lawn & Garden, Marine industries -> /", "Produces UL and CSA rated wire -> /", "Quality objectives: improve on-time delivery, reduce cost of quality, reduce scrap -> /quality"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='badger-wire' AND approved AND profile IS NULL;
UPDATE companies SET description='Banner Medical operates from Warsaw, Indiana, as a strategic business unit of Banner Industries, a division of A.M. Castle & Co. that has served the precision machining industry since 1961. The medical unit was established to supply raw materials and processing services to the medical device sector.

The company maintains an extensive inventory of medical-grade alloys including stainless steel, titanium, cobalt chrome, and 316LVM. Its in-house processing capabilities cover straightening, turning, grinding, and polishing of bar stock, as well as complete machining to near-net or finished component form. Additional services include packaging and special labeling, vendor-managed inventory programs, full material traceability to melt source, engineering and design support, and FDA 510(k) audit consultation.

Banner Medical serves medical device manufacturers and their supply chains, providing materials and components that meet stringent regulatory requirements.

The company differentiates itself through IQ, OQ, and PQ validation of its equipment per FDA protocol, asserting that its machining processes do not alter the physical properties of the material. It emphasizes rapid turnaround, vendor-managed inventory, and a defect-free quality target.', certifications=ARRAY['ISO 13485']::text[], profile='{"capabilities": ["Straightening", "Turning", "Grinding", "Polishing", "Complete machining to near-net or finished components", "Packaging and special labeling", "Vendor-managed inventory", "Material traceability to melt source", "Engineering and design support", "FDA 510(k) audit consultation", "Raw material sourcing"], "industries": ["Medical Devices", "Precision Machining"], "materials": ["Stainless Steel", "Titanium", "Cobalt Chrome", "316LVM", "Exotic medical grade alloys"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["IQ/OQ/PQ equipment validation per FDA protocol", "Machining processes verified not to change material physical properties", "Vendor-managed inventory programs", "Full material traceability to melt source", "FDA 510(k) audit and approval process consultation"], "facts_used": ["Founded 1961 -> db, /about-us", "Headquarters Warsaw, Indiana -> db", "Strategic business unit of Banner Industries, division of A.M. Castle & Co. -> /about-us", "ISO 13485 certified -> db, /, /about-us", "Processes: straightening, turning, grinding, polishing, complete machining -> /about-us", "Materials: stainless steel, titanium, cobalt chrome, 316LVM, exotic medical grade alloys -> /about-us", "Services: packaging, labeling, vendor-managed inventory, material traceability, engineering support, FDA 510(k) consultation -> /about-us", "Industries served: medical device, precision machining -> /about-us", "IQ/OQ/PQ validation per FDA protocol -> /, /about-us", "Machining does not change material physical properties -> /, /about-us", "Rapid turnaround claimed -> /", "Address: 494 East Lies Rd., Carol Strea