UPDATE companies SET description='Component Plastics Inc. (CPI) has operated from Elgin, Illinois since its founding in 1969. The company began as a Midwest injection molding source and has remained employee-owned throughout its history, a structure the firm credits for its ability to meet customer needs directly.

CPI specializes in custom injection molding, insert injection molding, and filter molding, including mesh insert production. Its capabilities extend to tool and die making, EDM/EDI, rapid prototyping, ultrasonic welding, supply chain management, and offshore tooling. The company supports low- to high-volume production runs for clients worldwide, applying scientific molding principles with upfront capability studies.

The manufacturer serves automotive, agricultural, industrial, medical, and telecommunications sectors. CPI notes that it still supplies its first customer from 1969, and its client base includes companies requiring vending machine components, medical device molding, and filtration solutions.

CPI emphasizes its people as its greatest differentiator, describing itself as a customer service company that molds. The firm highlights fast delivery, competitive rates, and a willingness to pivot for custom jobs, aiming to provide personalized solutions regardless of project size.', certifications=ARRAY['ISO 9001:2015','IATF 16949:2016']::text[], profile='{"capabilities": ["Custom Injection Molding", "Insert Injection Molding", "Filter Molding", "Mesh Insert Production", "Tool & Die", "EDM/EDI", "Rapid Prototyping", "Ultrasonic Welding", "Supply Chain Management", "Offshore Tooling", "Value-Added Services"], "industries": ["Automotive", "Agricultural", "Industrial", "Medical", "Telecommunications"], "materials": ["Polyamide (Nylon)", "HDPE", "LDPE", "ABS", "Polycarbonate"], "equipment": [], "volume": "Low to high volume production", "lead_time": "", "tolerances": "", "built_on": ["Employee-owned since 1969", "Scientific molding principles with upfront capability studies", "Fast delivery and competitive rates", "Customer service focused approach", "Worldwide low- to high-volume production capability"], "facts_used": ["Founded 1969 -> db", "Headquarters Elgin, Illinois -> db", "Employee-owned -> /capabilities", "ISO 9001:2015 certified -> /", "IATF 16949:2016 certified -> /", "Custom injection molding, insert injection molding, filter molding, mesh insert production -> /capabilities", "Tool & die, EDM/EDI, rapid prototyping, ultrasonic welding, supply chain capabilities, offshore tooling -> /capabilities, /about-us", "Low to high volume production -> /capabilities", "Scientific molding principles with upfront capability studies -> /about-us", "Industries: automotive, agricultural, industrial, medical, telecommunications -> /", "Still serves first customer from 1969 -> /capabilities", "Materials: polyamide (nylon), HDPE, LDPE, ABS, polycarbonate -> /", "Fast delivery and competitive rates -> /capabilities", "Customer service company that molds -> /capabilities", "Worldwide services -> /capabilities"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='component-plastics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Conneaut Industries has operated from West Greenwich, Rhode Island since its founding in 1930. The company remains family-owned and operated, now in its fourth generation, and describes itself as a "fourth-generation lead company" that has maintained continuous operations for over nine decades. No individual founders are named in public materials.

The firm specializes in textile converting, positioned between raw material manufacturers and end-use producers. Its core processes include precision winding, twisting, plying, cabling, and filler production. Conneaut works with a range of fibers such as fiberglass, aramids, cotton, polyester, nylon, PTFE-coated fiberglass, ultra-high-molecular-weight polyethylene (UHMWPE), S2-glass, PTFE yarn, and meta-aramids. It supplies these materials on various package types including cardboard tubes, wood reels, plastic serving spools, and industry-standard bobbins. Facility size and headcount are not disclosed.

Conneaut serves markets including aerospace, automotive, food processing, industrial, medical, oil and gas, sports and recreation, telecommunications, and durable goods. Specific applications cited by the company include electrical wire and cable, electronics, aerospace components, fiber optics, composite materials, ignition wire cores, magnet wire covering, braiding, weaving, knitting, and cordage.

The company emphasizes its nine-decade track record, a loyal low-turnover workforce, and a quality policy focused on continuous improvement and customer fulfillment. It holds ISO 9001:2015 certification and states that its globally sourced products are REACH and RoHS compliant and conflict-minerals free.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Precision winding", "Twisting", "Plying", "Cabling", "Filler production", "Custom yarn development", "High-performance yarn sourcing", "Textile converting", "Braiding", "Cordage manufacturing", "Roving production", "Double-twist cabling", "PolyGlass yarn production"], "industries": ["Aerospace", "Automotive", "Food Processing", "Industrial", "Medical", "Oil & Gas", "Sports & Recreation", "Telecommunications", "Durable Goods", "Electrical Wire & Cable", "Electronics", "Fiber Optics", "Composite Materials"], "materials": ["Fiberglass", "Aramid", "Cotton", "Polyester", "Nylon", "PTFE Coated Fiberglass", "UHMWPE", "S2-Glass Fiberglass", "PTFE Yarn", "Meta-Aramid"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned and operated since 1930 with continuous operations", "ISO 9001:2015 certified quality management", "REACH, RoHS compliant and conflict-minerals free sourcing", "Precision winding, twisting, plying, cabling, and filler expertise", "Custom development for high-performance and specialty yarns"], "facts_used": ["Founded in 1930 -> /, /about-us", "Family owned and operated since 1930 -> /, /about-us", "Fourth-generation lead company -> /, /about-us", "Headquarters: 89 Hopkins Hill Road, West Greenwich, RI 02817 -> /, /about-us", "ISO 9001:2015 certified -> /, /about-us, db", "REACH, RoHS compliant and Conflict Minerals Free -> /about-us", "Process capabilities: precision winding, twisting, plying, cabling, fillers -> /capabilities", "Materials: Fiberglass, Aramids, Cotton, Polyester, Nylon, PTFE Coated Fiberglass, UHMWPE, S2-Glass, PTFE Yarn, Meta