UPDATE companies SET description='Founded in 1945 in Bloomington, Minnesota, Dalsin Industries began as a metal fabrication shop built on principles of respect, hard work, and family values. The company has operated continuously for 80 years, evolving through strategic investments in automation and technology.

Today Dalsin provides full-service contract metal manufacturing and assembly for OEMs worldwide. Its capabilities span fiber laser cutting, high-volume sheet punching, automated panel bending and forming, robotic and manual welding, electro-mechanical assembly, and expert finishing. The company combines these processes with collaborative design assistance, design-for-manufacture optimization, production planning, and global supply chain management to deliver precision weldments, progressive stamped parts, and fabricated assemblies.

Dalsin serves industries including solar energy mounting and racking systems, fuel cell assemblies and enclosures, renewable energy storage, appliance, bus and recreational vehicle, automotive equipment, and DC racking and storage. Its customer base also extends to energy, transportation, power management, materials handling, and construction sectors, with long-term relationships spanning decades.

The company differentiates itself through a ''Better by Design'' philosophy that emphasizes early engineering collaboration to improve product performance and reduce costs. Sustainability initiatives include a rooftop solar array generating 46 percent of the facility''s electricity and zero-waste programs.', certifications=ARRAY['ISO 9001:2015','ISO 14001:2015','Green Waste Certification (2021)']::text[], profile='{"capabilities": ["Precision metal fabrication", "Sheet metal bending and forming", "Fiber laser cutting", "High-volume full sheet punching", "Automated panel bending and forming", "Robotic welding", "Manual welding", "Electro-mechanical assembly", "Finishing services", "Collaborative design assistance", "Design-for-manufacture (DFM) optimization", "Production planning and control", "Global supply chain management", "Progressive stamping", "Welding capabilities", "Punching capabilities"], "industries": ["Solar Energy Mounting / Racking Systems", "Fuel Cell Assemblies & Enclosures", "Renewable Energy Storage Systems", "Appliance", "Bus & Recreational Vehicle", "Automotive Equipment", "DC Racking & Storage Systems", "Energy", "Transportation", "Power Management", "Materials Handling", "Construction"], "materials": [], "equipment": ["Fiber laser cutting machines", "High-volume full sheet punching presses", "Automated panel bending and forming equipment", "Robotic welding cells"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Collaborative design and design-for-manufacture (DFM) optimization", "High-velocity automated manufacturing (robotic welding, automated bending, fiber laser cutting)", "Global supply chain management for worldwide OEMs", "On-site solar array supplying 46% of electrical needs and zero-waste initiatives", "Decades-long customer relationships with 96% satisfaction scores"], "facts_used": ["Founded 1945 -> db", "Headquarters Bloomington, Minnesota -> db", "80 years in business as of 2025 -> home page", "Principles of respect, hard work, family values -> about page", "Full-service contract metal manufacturing and assembly -> home page", "Processes: fiber laser cutting, high-volume sheet punching, automated panel bending and forming, robotic and manual welding, electro-mechanical assembly, finishing -> home page", "Collaborative design assistance, DFM optimization, production planning, global supply chain management -> home page", "Products: precision weldments, progressive stamped parts, fabricated assemblies -> home page", "Industries: solar energy mounting/racking, fuel cell assemblies/enclosures, renewable energy storage, appliance, bus & recreational vehicle, automotive equipment, DC racking & storage -> home page", "Additional industries: energy, transportation, power management, materials handling, construction -> about page", "Better by Design philosophy emphasizing early engineering collaboration -> home page", "Rooftop solar array generating 46% of facility electricity -> about page", "Zero-waste initiatives -> about page", "ISO 9001:2015 and ISO 14001:2015 certifications -> home page", "Green Waste certification pursued in 2021 -> about page", "Customer satisfaction 96%, loyalty top 2% -> home page", "Long-term customer relationships spanning decades -> about page"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='dalsin-industries-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='De Perini Metal Fabricators operates a 25,600-square-foot plant in the Montgomery County Airpark at Gaithersburg, Maryland, with convenient access to Interstates 270, 495, 95 and 695. The woman-owned Maryland corporation was established in 1960 and is managed by a professional staff that oversees both prototyping and full-scale production.

The facility houses sheet metal fabrication, machining, welding, assembly and finishing departments. Sheet metal work centers on an Amada 4-kW laser cutter and Strippit and Trumpf CNC punching systems, while machining relies on Haas VF-4 vertical machining centers capable of holding 0.005-inch tolerances. Certified welders perform TIG/MIG, spot, brazing and soldering to military specifications, and hardware insertion runs on Haeger equipment. Finishing includes Mil-Spec wet and powder coating, chemical conversion coating per MIL-DTL-5541 (Type 1 gold and RoHS-compliant Type 2 clear), and stainless-steel passivation to QQP35 and AMS 2700 standards.

De Perini serves military, government and commercial customers, fabricating parts from aluminum, steel, copper, stainless steel, bar stock and plastics. The shop handles both short- and long-term projects with scheduled deliveries.

The company emphasizes its ISO 9001:2015 quality system, continuous improvement and on-time delivery, with every employee responsible for quality verification before shipment.', certifications=ARRAY['ISO 9001:2015','MIL-DTL-5541','QQP35 Types 6 and 7','AMS 2700 Methods 1 and 2']::text[], profile='{"capabilities": ["Prototyping", "Production runs", "Shearing", "CNC punching", "CNC milling", "Laser cutting", "Forming", "Mil-Spec welding (TIG/MIG, spot, brazing, soldering)", "Assembly", "Hardware insertion", "Wet painting (Mil-Spec)", "Powder coating", "Chemical conversion coating (MIL-DTL-5541 Type 1 and Type 2)", "Stainless steel passivation (QQP35, AMS 2700)", "Silk screening", "Engraving", "Stenciling", "CNC machining", "Manual machining", "Quality inspection"], "industries": ["Military", "Government", "Commercial"], "materials": ["Aluminum", "Steel", "Copper", "Bar Stock", "Plastics", "Stainless Steel"], "equipment": ["Amada 4000 Watt Laser Cutting Machine", "Strippit CNC punching systems", "Trumpf CNC punching systems", "Haas VF-4 Vertical Machining Centers", "Haeger Insertion equipment", "FeatureCam software"], "volume": "", "lead_time": "", "tolerances": "\u00b10.005 in", "built_on": ["ISO 9001:2015 certified quality management system", "25,600 sq ft modern facility with laser, CNC punching, and machining centers", "Certified welders qualified for military, government, and commercial work", "Chemical conversion coating certified to MIL-DTL-5541 (Type 1 and Type 2)", "Stainless steel passivation to QQP35 and AMS 2700 specifications"], "facts_used": ["25,600 sq ft manufacturing plant in Montgomery County Airpark, Gaithersburg, Maryland -> /", "Established 1960, woman-owned Maryland corporation -> /", "Accessible from I-270, I-495, I-95, I-695 -> /", "ISO 9001:2015 certified -> /", "Prototyping and production runs -> /capabilities", "Shearing, CNC punching, CNC milling, laser cutting, forming -> /capabilities", "Mil-Spec welding (TIG/MIG, spot, brazing, soldering)