UPDATE companies SET description='Distinctive Plastics, Inc. (DPI) was founded in 1981 in Vista, California, to deliver high-quality injection molding services on time and within budget.

DPI provides full-service technical injection molding, covering product development, tooling design and manufacturing (both in-house and outsourced), injection molding including two-shot, multi-component, insert molding, and in-mold decoration (IMD). The facility includes a Class 8 clean room for medical device molding, and offers ultrasonic welding, component assembly, and other value-added services.

The company serves medical device manufacturers, electronics producers, sports and leisure equipment makers, and life science firms. Medical and electronics assemblies are produced in the certified clean room environment, while IMD capabilities support decorative and functional parts for consumer and industrial applications.

DPI positions itself as a pioneer in in-mold decoration technology, which reduces production steps and cost. The firm emphasizes its ISO 13485 and ISO 9001 certifications, FDA registration, and UL listing as foundations for regulated medical and electronic work.', certifications=ARRAY['ISO 13485:2016','ISO 9001:2015','FDA Registered','EcoVadis Bronze Medal','UL Listed']::text[], profile='{"capabilities": ["Technical Injection Molding", "Medical Device Molding", "Class 8 Clean Room Molding", "Two-Shot/Multi-Component Molding", "In-Mold Decoration (IMD)", "Insert Molding", "Ultrasonic Welding", "Component Assembly", "Product Design & DFM Analysis", "Mold Design & Manufacturing", "In-House Tooling", "Off-Shore Tooling", "Engineering Services", "Quality Assurance Systems", "Project Management", "ERP Systems"], "industries": ["Medical Device Molding and Assembly", "Electronics Molding and Assembly", "Sports and Leisure Equipment", "Life Science"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Full-service injection molding from design through assembly", "Class 8 clean room for medical device molding", "Pioneer in in-mold decoration (IMD) technology", "In-house mold design and manufacturing capability", "ISO 13485, ISO 9001, FDA registered, UL listed"], "facts_used": ["Founded 1981 -> db", "Headquarters Vista, California -> db", "ISO 13485:2016, ISO 9001:2015, FDA Registered, EcoVadis Bronze Medal, UL Listed -> /", "Full-service technical injection molding including product development, tooling, molding, assembly -> /", "Class 8 clean room for medical molding -> /", "Two-shot, multi-component, insert molding, in-mold decoration (IMD) -> /", "Ultrasonic welding and component assembly -> /", "Product design, DFM analysis, mold design and manufacturing (in-house and outsourced) -> /", "Industries: Medical Device Molding and Assembly, Electronics Molding and Assembly, Sports and Leisure Equipment, Life Science -> /", "Pioneer