UPDATE companies SET description='Electri-Cord Manufacturing Co. (ECM) was founded in 1946 in Westfield, Pennsylvania.

ECM provides turnkey contract manufacturing for custom wire harnesses, cable assemblies, power cords, box builds, control panels, and high-level assemblies. Its capabilities span custom wire harness fabrication, cable assembly with overmolding, UL508A-certified panel assembly, molding and overmolding, kitting, and printed circuit board assembly. The company operates multi-site production in the U.S., Mexico, and Asia, supporting low- to high-volume runs and offering global supply chain services including engineering support, product development, quality assurance, logistics, warehousing, and just-in-time distribution.

The company serves a diverse industrial base including automotive and transportation, defense and security, medical and life sciences, renewable energy, industrial machinery, data centers, telecommunications, and commercial and industrial equipment markets.

ECM differentiates itself through its Globally Local© model, which combines U.S.-based program management with offshore production capacity to reduce total cost of ownership and lead times. The firm emphasizes its 75-plus years of continuous operation, UL and CSA certifications alongside ISO 9001 and IATF 16949, and the ability to deliver UL508A-certified panel assemblies from print to completion.', certifications=ARRAY['ISO 9001','IATF 16949','UL','CSA']::text[], profile='{"capabilities": ["Contract Manufacturing", "Custom Wire Harness", "Cable Assembly", "Power Cord Assembly", "High-Level Assembly", "Panel Assembly (UL508A-certified)", "Custom Box Build", "Global Supply Chain Management", "Electronic Manufacturing Services (EMS)", "Supply Chain Engineering Support", "Product Development", "Quality Assurance", "Document Control", "Logistics Management", "Testing & Certification", "Kitting & Packaging", "Warehousing & Distribution", "Molding & Overmolding", "Kitting & Assembly", "Quality Control", "Printed Circuit Board Assembly (PCBA)", "Ultrasonic Welding", "Overmolded Housings and Strain Reliefs", "EV Charging Cable Assembly"], "industries": ["Industrial", "Mobility", "Machinery", "Medical", "Devices", "Lab Equipment", "Energy", "Storage & Distribution", "Renewable Energy", "Technology", "Data Centers", "Enterprise Devices", "Defense & Security", "Automotive & Transportation", "Medical & Life Sciences", "Alternative Energy", "Military", "Commercial & Industrial"], "materials": [], "equipment": [], "volume": "Low to high volume production runs", "lead_time": "", "tolerances": "", "built_on": ["Globally Local\u00a9 manufacturing model with U.S., Mexico, and Asia facilities", "Turnkey contract manufacturing from concept through end-of-life", "UL508A-certified panel assembly capability", "Just-in-time distribution from U.S. warehousing", "Over 75 years of continuous operation"], "facts_used": ["Founded 1946 -> db", "Headquarters Westfield, Pennsylvania -> db", "Certifications ISO9001, IATF16949 -> db", "UL and CSA certified -> /", "Capabilities: contract manufacturing, custom wire harness, cable assembly, power cord assembly, high-level assembly, panel assembly, custom box build, global supply chain, EMS -> /capabilities", "Industries served: industrial, mobility, machinery, medical, devices, lab equipment, energy, storage & distribution, renewable energy, technology, data centers, enterprise devices, defense & security, automotive & transportation -> /", "Plant locations: USA, Mexico, Brazil, China, Vietnam, Taiwan -> /", "Partner factories: China, Taiwan, Vietnam, Indonesia, Thailand -> /capabilities", "UL508A-certified panel assembly -> /capabilities", "Globally Local\u00a9 approach -> /capabilities", "Turnkey solutions from concept to end-of-life -> /capabilities", "Just-in-time distribution -> /capabilities", "75 years in business -> /capabilities", "Multi-site production in U.S., Mexico, Asia -> /capabilities", "Low to high volume production runs -> /capabilities"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ecm-electri-cord-manufacturing-co' AND approved AND profile IS NULL;
UPDATE companies SET description='EEEA Inc., based in Simpsonville, South Carolina, was founded in 1974 on a simple principle: put the customer first. The company began with a handshake and the question “How can we help you?” and has grown into an electronics manufacturing partner serving aerospace, defense, medical, industrial, and utility markets.

The company operates a 40,000-square-foot facility where it provides printed circuit board manufacturing (single-layer to multi-layer), surface-mount and through-hole assembly, mixed-technology builds, selective soldering, custom wire harnesses, control panel assemblies, and full electromechanical integration. Services also include quick-turn prototyping, reverse engineering, design engineering using Pads and AutoCAD, and 100% AOI inspection on all SMT boards. The team averages 15 years of industry experience, and there are no minimum order quantities.

EEEA serves aerospace, defense, medical, industrial, automotive, textile, and utility sectors. Examples include precision assemblies built to withstand demanding environments and regulatory standards for aerospace, reliable electronic controls for heavy-duty industrial applications, high-quality assemblies for life-saving medical devices, durable electronics for automotive components, advanced controls for high-performance textile machinery, and specialized electrical testing products such as breaker simulators and grounding testers for power and utility systems.

The company emphasizes a relationship-driven approach, ISO 9001:2015 and IPC-certified processes, dual AOI machines, Red Rabbit test systems, and a workforce with deep tenure as key differentiators. Its founding commitment to customer success continues to guide operations, with leadership including President Brent Buckner and a long-tenured production team.', certifications=ARRAY['ISO 9001:2015','IPC-A-610','J-STD-001']::text[], profile='{"capabilities": ["Printed circuit board manufacturing (single to multi-layer)", "Surface-mount technology (SMT) assembly", "Through-hole assembly", "Mixed-technology assembly", "Selective soldering", "Automated optical inspection (AOI)", "Turnkey assembly solutions", "Custom wire harness fabrication", "Point-to-point wiring", "Control panel assembly", "Quick-turn prototyping", "Small-batch production", "Reverse engineering", "Revision upgrades", "Functional testing", "Full operational testing", "Design engineering (Pads, AutoCAD)", "Flex-circuit production", "Electromechanical assembly"], "industries": ["Aerospace", "Defense", "Medical", "Industrial", "Automotive", "Textiles", "Utilities"], "materials": [], "equipment": ["Dual AOI machines", "Red Rabbit test systems", "Optical inspection equipment", "CNC driller/router"], "volume": "Prototype to full production runs, no minimum order quantity", "lead_time": "", "tolerances": "", "built_on": ["40,000 sq. ft. manufacturing facility", "No minimum order quantities", "100% AOI inspection on all SMT boards", "Dual AOI machines and Red Rabbit test systems", "Team averaging 15 years industry experience", "ISO 9001:2015 and IPC certified processes"], "facts_used": ["Founded 1974 -> db, /, /about-us", "Headquarters Simpsonville, South Carolina -> db, /, /about-us", "Facility size 40,000 sq. ft. -> /services", "Services: PCB manufacturing, SMT, through-hole, mixed-technology, selective soldering, wire harnesses, control panels, prototyping, reverse engineering, design engineering, AOI inspection -> /services, /about-us", "Team averages 15 years experience -> /about-us", "No minimum order quantities -> /services", "Industries served: aerospace, defense, medical, industrial, automotive, textiles, utilities -> /", "Certifications: ISO 9001:2015, IPC-A-610, J-STD-001 -> /quality, /, /about-us (Lisa Rollins bio)", "Equipment: dual AOI machines, Red Rabbit test systems, optical inspection, CNC driller/router -> /quality, /about-us (Lisa Rollins bio)", "President Brent Buckner -> /, /about-us, /services, /quality", "Founding principle: customer first, handshake -> /, /about-us", "Relationship-driven approach -> /services, /about-us"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='eeea-inc' AND approved AND profile IS NULL;
